import base64
from pathlib import Path

FILES = {
    "index.html": """""",
    "src/utils/gradients.js": """""",
    "src/components/FestCard.jsx": """""",
    "src/pages/FestDetail.jsx": """""",
}

updated = []
for path, b64 in FILES.items():
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
    updated.append(path)

print(f"Updated {len(updated)} files:")
for u in updated:
    print(f"  {u}")